// Real-Chrome Playwright verification test for our WebGL2 non-DX12 graphics backend.
// Verifies:
//  1. GLSL ES 3.00 shaders generated by runtime/web/vsemu_glsl.inc compile & link in Chrome WebGL2 (ANGLE).
//  2. WebGL2Encoder drains a real SharedArrayBuffer GwCtl/GwCmd resource queue, uploads an A8R8G8B8 texture,
//     pulls TVert vertices from the 4096-wide R32UI Data Texture via texelFetch, renders a triangle into the
//     FBO backbuffer, composites to canvas, and reads back exact expected BGRA pixels.
import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import * as esbuild from 'esbuild';
import { chromium } from 'playwright';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WEB_DIR = path.resolve(__dirname, '..');

test('WebGL2Encoder compiles GLSL ES 3.00 shaders and renders TVert + textured quad accurately in Chrome WebGL2', async () => {
  // Bundle WebGL2Encoder + proto into a single browser-runnable ESM string
  const built = await esbuild.build({
    stdin: {
      contents: `
        export * as P from './src/gpu/proto.ts';
        export { WebGL2Encoder } from './src/gpu/webgl2/encoder.ts';
      `,
      resolveDir: WEB_DIR,
      loader: 'ts',
    },
    bundle: true,
    format: 'esm',
    write: false,
  });
  const jsBundle = built.outputFiles[0].text;

  // Serve with COOP/COEP headers so SharedArrayBuffer works in Chrome
  const server = http.createServer((req, res) => {
    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
    res.setHeader('Cross-Origin-Embedder-Policy', 'require-corp');
    if (req.url === '/bundle.js') {
      res.writeHead(200, { 'Content-Type': 'application/javascript' });
      res.end(jsBundle);
      return;
    }
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('<!doctype html><html><body><canvas id="c" width="64" height="64"></canvas></body></html>');
  });
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;

  let browser;
  try {
    browser = await chromium.launch({
      channel: 'chrome',
      headless: true,
      args: ['--use-gl=angle', '--enable-webgl'],
    });
    const page = await browser.newPage();
    await page.goto(`http://127.0.0.1:${port}/`);

    const result = await page.evaluate(async () => {
      const { P, WebGL2Encoder } = await import('/bundle.js');
      const canvas = document.getElementById('c');
      const gl = canvas.getContext('webgl2');
      if (!gl) return { ok: false, error: 'no webgl2 context' };

      const sab = new SharedArrayBuffer(2 * 1024 * 1024);
      const u8 = new Uint8Array(sab);
      const u32 = new Uint32Array(sab);
      const f32 = new Float32Array(sab);
      const logs = [];

      // Memory layout inside SAB:
      const CTL_PTR = 0x1000;
      const RQ_PTR  = 0x10000;
      const RQ_CAP  = 0x40000;
      const DRAWS_PTR = 0x60000;
      const TV_PTR    = 0x70000;
      const K_PTR     = 0x80000;
      const PSC_PTR   = 0x90000;

      const cw = CTL_PTR >>> 2;
      u32[cw + P.C.magic] = P.GW_MAGIC;
      u32[cw + P.C.version] = P.GW_VERSION;
      u32[cw + P.C.layout] = P.LAYOUT;
      u32[cw + P.C.size] = P.CTL_BYTES;
      u32[cw + P.C.rqPtr] = RQ_PTR;
      u32[cw + P.C.rqCap] = RQ_CAP;

      // Helper to push a resource queue command
      let rqHead = 0;
      const pushCmd = (op, args, payload) => {
        const plen = payload ? payload.byteLength : 0;
        const len = (P.CMD_HDR + plen + 15) & ~15;
        const off = RQ_PTR + (rqHead & (RQ_CAP - 1));
        const w = off >>> 2;
        u32[w] = op;
        u32[w + 1] = len;
        for (let i = 0; i < 6; i++) u32[w + 2 + i] = args[i] || 0;
        if (payload) u8.set(payload, off + P.CMD_HDR);
        rqHead += len;
        u32[cw + P.C.rqHead] = rqHead;
      };

      // 1. Create a 2x2 A8R8G8B8 texture (ID=1) filled with solid GREEN (BGRA: 0, 255, 0, 255)
      pushCmd(P.Op.TexCreate, [1, 2, 2, 1, P.Fmt.A8R8G8B8, 0]);
      const texPx = new Uint8Array(2 * 2 * 4);
      for (let i = 0; i < 4; i++) { texPx[i * 4] = 0; texPx[i * 4 + 1] = 255; texPx[i * 4 + 2] = 0; texPx[i * 4 + 3] = 255; }
      pushCmd(P.Op.TexUpload, [1, 0, 2, 2, 8, 2], texPx);

      // 2. Write a full-screen triangle in TVert arena (3 vertices * 28 floats each)
      // Vertex color = white (1,1,1,1), UV = (0.5, 0.5)
      const verts = [
        [-1, -1, 0.5, 1],
        [ 3, -1, 0.5, 1],
        [-1,  3, 0.5, 1],
      ];
      for (let i = 0; i < 3; i++) {
        const base = (TV_PTR >>> 2) + i * 28;
        f32[base + 0] = verts[i][0]; f32[base + 1] = verts[i][1]; f32[base + 2] = verts[i][2]; f32[base + 3] = verts[i][3];
        f32[base + 4] = 1; f32[base + 5] = 1; f32[base + 6] = 1; f32[base + 7] = 1; // col0
        f32[base + 12] = 0.5; f32[base + 13] = 0.5; f32[base + 14] = 0; f32[base + 15] = 1; // uv0
      }

      // 3. Record 1 GwDraw (TVert path vsid=0, ps=0, tex=1, no cull, no depth)
      const dw = DRAWS_PTR >>> 2;
      u32[dw + P.D.first] = 0;
      u32[dw + P.D.count] = 3;
      u32[dw + P.D.tex] = 1;
      u32[dw + P.D.target] = 0;
      u32[dw + P.D.kind] = P.Kind.Draw;
      u32[dw + P.D.blend] = 0xF << 14; // writeMask RGBA, blend off
      f32[dw + P.D.aref] = 0;
      u32[dw + P.D.depth] = 0;
      u32[dw + P.D.ps] = 0;
      u32[dw + P.D.psci] = 0;
      u32[dw + P.D.vsid] = 0;
      u32[dw + P.D.cull] = 1; // D3DCULL_NONE

      // 4. Populate GwFrame[0]
      const fw = cw + P.C.frame;
      u32[fw + P.F.seq] = 1;
      u32[fw + P.F.dn] = 1;
      u32[fw + P.F.vn] = 3;
      u32[fw + P.F.draws] = DRAWS_PTR;
      u32[fw + P.F.tv] = TV_PTR;
      u32[fw + P.F.k] = K_PTR;
      u32[fw + P.F.psc] = PSC_PTR;
      u32[fw + P.F.rqEnd] = rqHead;
      u32[fw + P.F.bbW] = 64;
      u32[fw + P.F.bbH] = 64;
      u32[fw + P.F.clearArgb] = 0xFFFF0000; // Red clear (should be overwritten by green triangle!)

      const enc = new WebGL2Encoder(gl, { buffer: sab }, CTL_PTR, s => logs.push(s));
      enc.drain(rqHead);
      const st = enc.encodeFrame(0);
      enc.compositeToCanvas(64, 64, null);
      const rb = enc.readbackBgra(0);
      const center = (32 * 64 + 32) * 4;
      const bgra = rb ? [rb.data[center], rb.data[center + 1], rb.data[center + 2], rb.data[center + 3]] : null;
      // 5. Also verify translated D3D9 vs_1_1 + ps_1_1 shaders via raw vertex arena + VSWin UBO + PSPar UBO
      const rawVsSrc = `#version 300 es
precision highp float;
precision highp int;
vec4 sat(vec4 x) { return clamp(x, 0.0, 1.0); }
float satf(float x) { return clamp(x, 0.0, 1.0); }
out vec4 v_col0; out vec4 v_col1;
out vec4 v_uv0; out vec4 v_uv1; out vec4 v_uv2; out vec4 v_uv3;
out float v_fog;
layout(std140) uniform VSWin { vec4 c[1024]; } K;
uniform highp usampler2D u_vb;
uniform uint u_kb;
uniform int u_vbase;
uniform float u_yflip;
uint vb_word(uint w) { return texelFetch(u_vb, ivec2(int(w & 4095u), int(w >> 12u)), 0).r; }
uint ld32(uint a) {
  uint w = a >> 2u; uint s = (a & 3u) << 3u;
  if (s == 0u) return vb_word(w);
  return (vb_word(w) >> s) | (vb_word(w + 1u) << (32u - s));
}
float ldf(uint a) { return uintBitsToFloat(ld32(a)); }
vec4 ldub4(uint a) { uint u = ld32(a); return vec4(float(u & 0xFFu), float((u >> 8u) & 0xFFu), float((u >> 16u) & 0xFFu), float(u >> 24u)); }
vec4 n8(vec4 x) { return x * (1.0 / 255.0); }
vec4 ldcolor(uint a) { return n8(ldub4(a).zyxw); }
vec4 tpick(uint s, vec4 a, vec4 b, vec4 c, vec4 d) { return (s >= 2u) ? ((s == 3u) ? d : c) : ((s == 1u) ? b : a); }
void main() {
  uint vid = uint(gl_VertexID + u_vbase);
  uvec4 KH = floatBitsToUint(K.c[u_kb]);
  uint B = KH.z + vid * KH.x;
  vec4 v0 = vec4(ldf(B + 0u), ldf(B + 4u), ldf(B + 8u), 1.0);
  vec4 v1 = ldcolor(B + 12u);
  vec4 v2 = vec4(ldf(B + 16u), ldf(B + 20u), 0.0, 1.0);
  vec4 oPos = vec4(dot(v0, K.c[u_kb + 1u]), dot(v0, K.c[u_kb + 2u]), dot(v0, K.c[u_kb + 3u]), dot(v0, K.c[u_kb + 4u]));
  gl_Position = vec4(oPos.x, oPos.y * u_yflip, oPos.z * 2.0 - oPos.w, oPos.w);
  v_col0 = v1; v_col1 = vec4(0.0);
  v_uv0 = tpick(KH.y & 3u, v2, vec4(0.0), vec4(0.0), vec4(0.0));
  v_uv1 = vec4(0.0); v_uv2 = vec4(0.0); v_uv3 = vec4(0.0);
  v_fog = 1.0;
}
`;
      const rawPsSrc = `#version 300 es
precision highp float;
precision highp int;
vec4 sat(vec4 x) { return clamp(x, 0.0, 1.0); }
float satf(float x) { return clamp(x, 0.0, 1.0); }
in vec4 v_col0; in vec4 v_col1;
in vec4 v_uv0; in vec4 v_uv1; in vec4 v_uv2; in vec4 v_uv3;
in float v_fog;
out vec4 fragColor;
#ifndef ALPHA_FUNC
#define ALPHA_FUNC 7u
#endif
layout(std140) uniform PSPar { float aref; float usec; float pad0; float pad1; vec4 proj; vec4 c[32]; vec4 fog; } P;
uniform sampler2D tex0;
vec4 ps_end(vec4 col, float fog) {
  if (ALPHA_FUNC != 8u && col.a < P.aref) discard;
  return vec4(mix(P.fog.rgb, col.rgb, mix(1.0, satf(fog), P.fog.a)), col.a);
}
void main() {
  fragColor = ps_end(texture(tex0, v_uv0.xy) * v_col0, v_fog);
}
`;
      const encTxt = new TextEncoder();
      const vsBytes = encTxt.encode(rawVsSrc + '\0');
      const psBytes = encTxt.encode(rawPsSrc + '\0');
      pushCmd(P.Op.ShaderVs, [1, vsBytes.length], vsBytes);
      pushCmd(P.Op.ShaderPs, [1, psBytes.length], psBytes);

      // Raw vertex arena at 0xA0000: 3 vertices, stride 24 bytes (FLOAT3 pos, D3DCOLOR blue 0xFF0000FF, FLOAT2 uv)
      const RAW_PTR = 0xA0000;
      const dv = new DataView(sab);
      const rawVerts = [[-1, -1, 0.5], [3, -1, 0.5], [-1, 3, 0.5]];
      for (let i = 0; i < 3; i++) {
        const o = RAW_PTR + i * 24;
        dv.setFloat32(o + 0, rawVerts[i][0], true);
        dv.setFloat32(o + 4, rawVerts[i][1], true);
        dv.setFloat32(o + 8, rawVerts[i][2], true);
        dv.setUint32(o + 12, 0xFF0000FF, true); // D3DCOLOR ARGB -> pure BLUE (R=0,G=0,B=255,A=255)
        dv.setFloat32(o + 16, 0.5, true);
        dv.setFloat32(o + 20, 0.5, true);
      }
      // VSWin K block at K_PTR + 2048: header {stride=24, tsel=0, base=0, target=0} + identity 4x4 matrix in c0..c3
      const K_OFF = 2048;
      const kw = (K_PTR + K_OFF) >>> 2;
      u32[kw + 0] = 24; u32[kw + 1] = 0; u32[kw + 2] = 0; u32[kw + 3] = 0;
      f32[kw + 4] = 1; f32[kw + 9] = 1; f32[kw + 14] = 1; f32[kw + 19] = 1;

      // Record frame 2 draw using vsid=1, ps=1, white texture (id=0) -> should render pure BLUE (BGRA: 255, 0, 0, 255)
      u32[dw + P.D.first] = 0;
      u32[dw + P.D.count] = 3;
      u32[dw + P.D.tex] = 0; // white
      u32[dw + P.D.ps] = 1;
      u32[dw + P.D.vsid] = 1;
      u32[dw + P.D.rawoff] = 0;
      u32[dw + P.D.koff] = K_OFF;
      u32[dw + P.D.ksz] = 16 + 16 * 4;
      u32[fw + P.F.seq] = 2;
      u32[fw + P.F.dn] = 1;
      u32[fw + P.F.vn] = 0;
      u32[fw + P.F.rvn] = 3 * 24;
      u32[fw + P.F.kn] = K_OFF + 16 * 8;
      u32[fw + P.F.raw] = RAW_PTR;
      u32[fw + P.F.rqEnd] = rqHead;

      enc.drain(rqHead);
      const st2 = enc.encodeFrame(0);
      const rb2 = enc.readbackBgra(0);
      const bgra2 = rb2 ? [rb2.data[center], rb2.data[center + 1], rb2.data[center + 2], rb2.data[center + 3]] : null;
      enc.destroy();
      return { ok: true, draws: st.draws, draws2: st2.draws, passes: st.passes, errors: enc.errors, bgra, bgra2, logs };
    });

    assert.equal(result.ok, true, result.error || 'eval failed');
    assert.equal(result.errors, 0, `WebGL2 shader/program errors: ${result.logs.join('\n')}`);
    assert.equal(result.draws, 1);
    assert.equal(result.draws2, 1);
    // Frame 1: solid GREEN from A8R8G8B8 texture via TVert R32UI vertex pulling
    assert.deepEqual(result.bgra, [0, 255, 0, 255]);
    // Frame 2: solid BLUE from D3DCOLOR raw vertex pulling + VSWin UBO identity matrix + ps_1_1
    assert.deepEqual(result.bgra2, [255, 0, 0, 255]);
  } finally {
    if (browser) await browser.close();
    server.close();
  }
});
